// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract Recorder {
    uint256 public callCount;
    bytes4 public lastSelector;
    address public lastFrom;
    address public lastTo;
    uint256 public lastAmount;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        callCount++;
        lastSelector = msg.sig;
        lastFrom = from;
        lastTo = to;
        lastAmount = amount;
        return true;
    }
}

contract InvMutTest is Test {
    demo c;
    Recorder r;

    function setUp() public {
        c = new demo();
        r = new Recorder();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        uint256 n = tos.length;
        if (n == 0) return;
        if (n > 20) return;

        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(tos[i], i))) | 1));
        }

        uint256 beforeCount = r.callCount();

        bool ok;
        try c.transfer(from, address(r), tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        if (!ok) return;

        uint256 afterCount = r.callCount();
        uint256 delta = afterCount - beforeCount;

        assertTrue(delta == n);
    }
}
